"""Batch job runner migrated from Meridian CRM 4.2 semantics."""

from typing import Any, Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], Any]) -> list[dict]:
    """Run scheduled jobs sequentially according to their error policies.

    The executor is called once per attempt and may raise any Exception to
    indicate failure. Job failures are recorded in the returned log and do not
    escape from this function.
    """
    run_log: list[dict] = []

    for job in jobs:
        on_error = job["on_error"]
        policy = on_error["policy"]

        if policy == "RETRY":
            max_attempts = on_error["retries"] + 1
        else:
            max_attempts = 1

        attempts = 0
        succeeded = False

        while attempts < max_attempts:
            attempts += 1
            try:
                executor(job)
            except Exception:
                continue
            else:
                succeeded = True
                break

        if succeeded:
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )
            continue

        if policy == "CONTINUE":
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "skip",
                    "audits": ["BATCH_ROWSKIP"],
                }
            )
            continue

        run_log.append(
            {
                "name": job["name"],
                "attempts": attempts,
                "outcome": "abort",
                "audits": [],
            }
        )
        break

    return run_log
